import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.*;
import java.nio.file.*;
import java.util.*;
public class BoardCoreAudit extends GhidraScript{
 public void run()throws Exception{Path out=Paths.get(getScriptArgs()[0]);Files.createDirectories(out);Set<Function> selected=new LinkedHashSet<>();var it=currentProgram.getFunctionManager().getFunctions(true);StringBuilder index=new StringBuilder(),strings=new StringBuilder();while(it.hasNext()){var f=it.next();String name=f.getName(true);index.append(f.getEntryPoint()).append("\t").append(name).append("\n");if(name.equals("MVD_Algorithm_CreateHandle")||name.equals("MVD_Algorithm_Process"))selected.add(f);if(name.contains("security_check_cookie"))f.setNoReturn(false);}Files.writeString(out.resolve("functions.tsv"),index.toString());var data=currentProgram.getListing().getDefinedData(true);while(data.hasNext()){var item=data.next();if(!item.hasStringValue())continue;String text=String.valueOf(item.getValue());if(text.contains("CalibBoard")||text.equals("Circularity")||text.equals("EdgeThreshLow")){strings.append(item.getAddress()).append("\t").append(text.length()>250?text.substring(0,250):text).append("\n");for(var r:getReferencesTo(item.getAddress())){var f=getFunctionContaining(r.getFromAddress());if(f!=null){strings.append("ref\t").append(f.getEntryPoint()).append("\n");selected.add(f);}}}}Files.writeString(out.resolve("strings.tsv"),strings.toString());var dec=new DecompInterface();dec.openProgram(currentProgram);for(var f:selected)if(!f.isExternal()){f.setNoReturn(false);var result=dec.decompileFunction(f,30,monitor);if(result.decompileCompleted())Files.writeString(out.resolve(f.getEntryPoint()+".c"),result.getDecompiledFunction().getC());}dec.dispose();}
}
